const api = ($env.GITHUB_API_URL || 'https://api.github.com');
const repo = 'Erik142/infra-homelab';
const gh = async (path) => this.helpers.httpRequest({
  method: 'GET', url: api + path, json: true,
  headers: { Authorization: 'Bearer ' + $env.GITHUB_TOKEN_MONITOR, Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
});
const claude = async (prompt) => this.helpers.httpRequest({
  method: 'POST', url: ($env.ANTHROPIC_BASE_URL || 'https://api.anthropic.com') + '/v1/messages', json: true,
  headers: { 'x-api-key': $env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' },
  body: { model: 'claude-haiku-5-5', max_tokens: 1500, messages: [{ role: 'user', content: prompt }] },
});

// Denylist: any hit is a human decision, whatever the review says.
const DENY = [/(^|\/)vault\.yml$/, /(^|\/)\.github\//, /ssh_authorized_keys/, /^[^/]+\/roles\/(security|firewall|caddy|zero.?tier|podman|semaphore)\//, /^pi-[^/]+\//];
// Allowlist: the only paths an automerge candidate may change.
// Paths in this monorepo start with the host directory, e.g. nas-de-int-wahlberger-dev/roles/...
const ALLOW = [/^[^/]+\/roles\/[^/]+\/(defaults|templates)\//, /(^|\/)requirements\.yml$/];
const BUDGET_FILES = 6, BUDGET_LINES = 60;

const prs = (await gh('/repos/' + repo + '/pulls?state=open&per_page=50')).filter((p) => String(p.head.ref).startsWith('renovate/'));
const decisions = [];
for (const pr of prs) {
  const base = { pr: pr.number, title: pr.title, sha: pr.head.sha, mode: 'monitor-only', loop: 0 };
  const files = await gh('/repos/' + repo + '/pulls/' + pr.number + '/files?per_page=100');
  // Actions: read is enough for workflow runs. Checks is not a fine-grained token permission.
  const checks = ((await gh('/repos/' + repo + '/actions/runs?head_sha=' + pr.head.sha + '&per_page=100')).workflow_runs || []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
  const lines = files.reduce((n, f) => n + f.additions + f.deletions, 0);
  const major = /\|\s*major\s*\|/i.test(pr.body || '');
  const reasons = [];
  if (major) reasons.push('major update: human only');
  for (const f of files) if (DENY.some((r) => r.test(f.filename))) reasons.push('denylisted path: ' + f.filename);
  for (const f of files) if (!ALLOW.some((r) => r.test(f.filename))) reasons.push('outside allowlist: ' + f.filename);
  if (files.length > BUDGET_FILES || lines > BUDGET_LINES) reasons.push('over budget: ' + files.length + ' files, ' + lines + ' lines');
  const pending = checks.filter((c) => c.status !== 'completed');
  const failed = checks.filter((c) => c.status === 'completed' && c.conclusion !== 'success' && c.conclusion !== 'skipped' && c.conclusion !== 'neutral');
  if (failed.length) reasons.push('CI failed: ' + failed.map((c) => c.name).join(', '));
  if (!checks.length) reasons.push('no CI results yet');
  if (reasons.some((r) => r.startsWith('major') || r.startsWith('denylisted') || r.startsWith('outside') || r.startsWith('over budget') || r.startsWith('CI failed'))) {
    decisions.push({ ...base, decision: 'escalate', reasons }); continue;
  }
  if (pending.length || !checks.length) { decisions.push({ ...base, decision: 'wait', reasons }); continue; }

  const diff = files.map((f) => '--- ' + f.filename + '\n' + String(f.patch || '').slice(0, 8000)).join('\n').slice(0, 20000);
  const prompt = 'Review this Renovate dependency PR for merge safety. The repository is a homelab Ansible repo. Reply with one JSON object and nothing else: no prose, no code fences, at most 120 words in total. Shape: {"verdict":"safe|fixable|unsafe","reasons":["..."],"patch_summary":"..."}. Use "fixable" only if a small change within roles/*/defaults, roles/*/templates or requirements.yml would make it safe; describe it in patch_summary. Title: ' + pr.title + '\n\nDiff:\n' + diff;
  const resp = await claude(prompt);
  const text = (resp.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('');
  let verdict = null;
  const cleaned = text.replace(/```(json)?/g, '');
  try { verdict = JSON.parse(cleaned.slice(cleaned.indexOf('{'), cleaned.lastIndexOf('}') + 1)); } catch (e) { verdict = null; }
  if (!verdict || !['safe', 'fixable', 'unsafe'].includes(verdict.verdict)) {
    const why = resp.stop_reason === 'max_tokens' ? 'review cut off at the token limit' : 'review output not valid JSON';
    decisions.push({ ...base, decision: 'escalate', reasons: [why] }); continue;
  }
  const decision = verdict.verdict === 'safe' ? 'would_merge' : verdict.verdict === 'fixable' ? 'would_fix' : 'escalate';
  decisions.push({ ...base, decision, review: verdict.verdict, reasons: [...reasons, ...(verdict.reasons || [])], patch_summary: verdict.patch_summary || '' });
}
return [{ json: { mode: 'monitor-only', polled_at: new Date().toISOString(), decisions } }];
